/*============================================================================
** Function Name:    HmLanguage1GetStringLen
** Visibility:		 local
** Description:		 Returns the string length for the passed SID
** Invocation:		 By HmLanguage1GetString
** Inputs/Outputs:	 SID
** Critical Section: String Length
** Created:          16-Aug-2010 by EMANOJ1
** Updated:          16-Aug-2010 by EMANOJ1
**==========================================================================*/
static UINT16 HmLanguage1GetStringLen(LANG_SID_T p_sid)
{
   UINT16 fl_string_length_U16 = 0U;
   if(p_sid < HM_LANG_BUFFER_MAX_SIZE)
   {
     UINT8 const *p_lang_db_U8P      = (UINT8 const *)&HmStrLngTable1[p_sid];
     UINT8 fl_temp_U8;
     UINT8 fl_command_byte_U8;

     do
     {
        fl_command_byte_U8 = *p_lang_db_U8P;
        fl_temp_U8         = (UINT8)(fl_command_byte_U8  & HMI_LNG_CMD_LENGTH_MASK);
        fl_string_length_U16++;
        if(fl_temp_U8 == HMI_LNG_CMD_LENGTH_MASK)
        {
           /* We got another SID */
           if((fl_command_byte_U8 & HMI_LNG_CMD_EXT_ESID_BIT) != 0U)
           {
              fl_temp_U8 = 3U;
           }
           else
           {
              fl_temp_U8 = 2U;
           }
        }
        p_lang_db_U8P++;
        fl_string_length_U16 += (UINT16)fl_temp_U8;
        p_lang_db_U8P        = &p_lang_db_U8P[fl_temp_U8];
     }
     while((fl_command_byte_U8 & HMI_LNG_CMD_LINK_BIT) != 0U);
   }

   return(fl_string_length_U16);
}

